BEGIN;
ALTER TABLE users ADD COLUMN region text;
COMMIT;

-- backfill in batches so no single statement holds locks on the whole table
UPDATE users SET region = 'unknown'
WHERE id IN (SELECT id FROM users WHERE region IS NULL ORDER BY id LIMIT 5000);
-- (the deploy repeats the statement above until it updates 0 rows)

ALTER TABLE users ALTER COLUMN region SET DEFAULT 'unknown';

CREATE INDEX CONCURRENTLY users_region_idx ON users (region);

ALTER TABLE users ADD CONSTRAINT users_region_set CHECK (region IS NOT NULL) NOT VALID;
ALTER TABLE users VALIDATE CONSTRAINT users_region_set;
